<?php
$docs=db()->query("SELECT d.*, v.document_date AS current_document_date, v.version_label AS current_version FROM qm_documents d LEFT JOIN qm_document_versions v ON v.document_id=d.id AND v.is_current=1 ORDER BY d.document_number")->fetchAll();
$versions=db()->query("SELECT v.*, d.document_number FROM qm_document_versions v JOIN qm_documents d ON d.id=v.document_id ORDER BY d.document_number, v.document_date DESC")->fetchAll();
?>
<div class="panel"><h2>QM-Dokumente</h2><form class="ajax-form form-grid" action="ajax/qm_documents.php" data-reload="qm_documents" method="post"><?= csrfField() ?><input type="hidden" name="action" value="save_doc"><input type="hidden" name="id" value="0"><label>Interne Nummer<input name="document_number" placeholder="QMV 19" required></label><label>Name<input name="title" required></label><label>Dokumenttyp<input name="document_type"></label><label>Status<select name="status"><option>aktiv</option><option>ersetzt</option><option>aus_qm_entfernt</option></select></label><label>Notizen<textarea name="notes"></textarea></label><div><button>Dokument anlegen</button></div></form></div>
<div class="panel"><h3>Neue Version anlegen</h3><form class="ajax-form form-grid" action="ajax/qm_documents.php" data-reload="qm_documents" method="post"><?= csrfField() ?><input type="hidden" name="action" value="add_version"><label>Dokument<select name="document_id"><?php foreach($docs as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['document_number'].' - '.$d['title']) ?></option><?php endforeach; ?></select></label><label>Dokumentendatum<input type="date" name="document_date" required></label><label>Version<input name="version_label"></label><label>Änderung<select name="change_type"><option value="aktualisiert">aktualisiert</option><option value="neu_erstellt">neu erstellt</option><option value="aus_qm_entfernt">aus QM entfernt</option></select></label><label>Notizen<textarea name="notes"></textarea></label><div><button>Version speichern</button></div></form></div>
<div class="panel"><table class="data-table js-data-table"><thead><tr><th>Interne Nummer</th><th>Name</th><th>Dokumenttyp</th><th>aktuelles Dokumentendatum</th><th>aktuelle Version</th><th>Status</th><th>Aktionen</th></tr></thead><tbody><?php foreach($docs as $d): ?><tr><td><?= e($d['document_number']) ?></td><td><?= e($d['title']) ?></td><td><?= e($d['document_type']) ?></td><td><?= e($d['current_document_date']) ?></td><td><?= e($d['current_version']) ?></td><td><?= statusBadge($d['status']) ?></td><td class="muted">Bearbeiten über Formular vorbereiten</td></tr><?php endforeach; ?></tbody></table></div>
<div class="panel"><h3>Versionshistorie</h3><table class="data-table"><thead><tr><th>Dokument</th><th>Datum</th><th>Version</th><th>Änderung</th><th>Aktuell</th></tr></thead><tbody><?php foreach($versions as $v): ?><tr><td><?= e($v['document_number']) ?></td><td><?= e($v['document_date']) ?></td><td><?= e($v['version_label']) ?></td><td><?= e($v['change_type']) ?></td><td><?= (int)$v['is_current']?'ja':'nein' ?></td></tr><?php endforeach; ?></tbody></table></div><script>initDataTable('.js-data-table');</script>
